Load the fonts with next/font: // Save these files beside layout.tsx in ./fonts/ (retain LICENSE.txt):
// https://bash-ui-registry.vercel.app/fonts/open-runde/OpenRunde-Regular.woff2
// https://bash-ui-registry.vercel.app/fonts/open-runde/OpenRunde-Medium.woff2
// https://bash-ui-registry.vercel.app/fonts/open-runde/OpenRunde-Semibold.woff2
// https://bash-ui-registry.vercel.app/fonts/open-runde/OpenRunde-Bold.woff2
// https://bash-ui-registry.vercel.app/fonts/open-runde/LICENSE.txt
import localFont from "next/font/local";
const openRunde = localFont({
  src: [
    { path: "./fonts/OpenRunde-Regular.woff2", weight: "400" },
    { path: "./fonts/OpenRunde-Medium.woff2", weight: "500" },
    { path: "./fonts/OpenRunde-Semibold.woff2", weight: "600" },
    { path: "./fonts/OpenRunde-Bold.woff2", weight: "700" },
  ],
  variable: "--font-open-runde",
  display: "swap",
});
